/* Industrial case views share one run; reference studies require an explicit source change. */
(()=>{'use strict';
const H=window.HaloWorkspace,S=window.HaloSession,$=id=>document.getElementById(id);
const esc=v=>String(v??'—').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const num=(v,n=1)=>v==null?'—':Number(v).toLocaleString(undefined,{maximumFractionDigits:n});
const words=v=>String(v??'').replaceAll('_',' ');
const views=['actions','evidence','maintenance','passport','demo','integrations','twin','arena'];
let blindCase=null,data=null,validation=null,references=[],loading=false,reloadAgain=false,busy=false,csvText='',csvName='',csvSource='synthetic',lastRun='',maintenanceScope='simulation';
const view=()=>document.querySelector('.view.active')?.id.replace('view-','');
const endpoint=suffix=>'/twin/runs/'+encodeURIComponent(S.run().id)+suffix;
const api=(path,body)=>H.api(path,body);
function panel(name=view()){return $('case-'+name);}
function heading(title,note){const imported=view()==='maintenance'&&maintenanceScope==='reference';return `<div class="case-heading"><div><p class="eyebrow">${imported?'IMPORTED RECORDING REVIEW · SOURCE SHOWN BELOW':view()==='evidence'?'OBSERVATION REVIEW · CASE SOURCE SHOWN BELOW':esc(data.run.id)+' · INDUSTRIAL SIMULATION'}</p><h1>${title}</h1><p>${note}</p></div><div class="case-actions"><button data-case="refresh">Refresh</button>${imported?'':'<button data-case="export">Download selected run ↗</button>'}</div></div>`;}
const table=(heads,rows)=>`<div class="case-table"><table><thead><tr>${heads.map(h=>`<th>${esc(h)}</th>`).join('')}</tr></thead><tbody>${rows.map(row=>`<tr>${row.map(v=>`<td>${v}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
const kpis=rows=>`<div class="case-kpis">${rows.map(([label,value,note])=>`<div><span>${esc(label)}</span><strong>${esc(value)}</strong><small>${esc(note||'')}</small></div>`).join('')}</div>`;
const notice=message=>`<div class="case-alert">${esc(message)}</div>`;
const field=(label,name,value,type='text',attrs='')=>`<label>${label}<input name="${name}" type="${type}" value="${esc(value)}" ${attrs}></label>`;
function chart(series,horizon=30,startLabel='Forecast origin',endLabel=null,description='Temperature trajectories in degrees Celsius'){
 const vals=series.flatMap(s=>s.points.map(p=>p[1])).filter(Number.isFinite);if(!vals.length)return '<p>No qualified observations yet.</p>';
 let lo=Math.min(...vals),hi=Math.max(...vals);const pad=Math.max(2,(hi-lo)*.15);lo-=pad;hi+=pad;
 const width=Math.max(250,Math.min(600,window.innerWidth-100)),right=width-20;const x=m=>48+m/horizon*(right-48),y=v=>195-(v-lo)/(hi-lo)*165;let out='';
 for(let i=0;i<4;i++){const v=lo+(hi-lo)*i/3;out+=`<line x1="48" x2="${right}" y1="${y(v)}" y2="${y(v)}" stroke="#d7e1d9"/><text x="2" y="${y(v)+5}" font-size="15" fill="#566d61">${num(v)}</text>`;}
 for(const s of series){let path='',connected=false;for(const [m,v]of s.points){if(!Number.isFinite(v)){connected=false;continue;}path+=`${connected?'L':'M'}${x(m)},${y(v)} `;connected=true;}out+=`<path d="${path}" fill="none" stroke="${s.color}" stroke-width="3" ${s.dash?'stroke-dasharray="6 5"':''}/>`;}
 return `<svg class="case-chart" style="max-width:${width}px" viewBox="0 0 ${width} 235" role="img" aria-label="${esc(description)}">${out}<text x="48" y="225" font-size="15" fill="#566d61">${esc(startLabel)}</text><text x="${right}" text-anchor="end" y="225" font-size="15" fill="#566d61">${esc(endLabel||`+${horizon} min`)}</text></svg><div class="case-legend">${series.map(s=>`<span style="--line:${s.color}">${esc(s.label)}</span>`).join('')}</div>`;
}
function error(message){const p=panel();if(p){let node=p.querySelector('.case-inline-error');if(!node){node=document.createElement('p');node.className='case-inline-error';node.setAttribute('role','alert');p.prepend(node);}node.textContent=message;}H.toast(message);}
async function task(fn){
 if(busy)return;const drafts=Array.from(panel()?.querySelectorAll('form')||[]).map(f=>({id:f.id,work:f.dataset.work,fields:Array.from(f.elements).filter(e=>e.name&&e.type!=='file').map(e=>({name:e.name,value:e.value,checked:e.checked}))}));
 busy=true;document.querySelectorAll('.industrial-panel button').forEach(b=>b.disabled=true);let failure=null;
 try{await fn();}catch(e){failure=e.message;}finally{busy=false;if(data&&S.industrial()&&panel())render();if(failure){for(const d of drafts){const f=d.id?$(d.id):panel()?.querySelector('form[data-work="'+CSS.escape(d.work)+'"]');for(const v of d.fields){const e=f?.elements.namedItem(v.name);if(e){e.value=v.value;if(e.type==='checkbox')e.checked=v.checked;}}}error(failure);}}
}
async function load(){
 if(!S.industrial()||!S.run())return;if(loading){reloadAgain=true;return;}loading=true;const id=S.run().id;
 try{const r=await api('/twin/runs/'+encodeURIComponent(id)+'/case');if(!S.industrial()||S.run()?.id!==id)return;if(r.run.revision<S.run().revision){reloadAgain=true;return;}data=r;S.bind(r.run);render();}
 catch(e){error(e.message);}finally{loading=false;if(reloadAgain){reloadAgain=false;await load();}}
}
function study(horizon=30,maxDelay=0){return {request_id:crypto.randomUUID(),revision:data.run.revision,horizon_min:horizon,max_delay_min:maxDelay};}
function investigation(){const i=data.investigation;return `<section class="case-panel"><p class="eyebrow">EVIDENCE → NEXT CHECK</p><h2>${esc(i.title)}</h2><p>${esc(i.next_check)}</p>${i.observation_assessment?`<p class="case-muted">Observation-only assessment: <strong>${esc(words(i.observation_assessment.hypotheses?.length?i.observation_assessment.hypotheses.join(' + '):i.observation_assessment.hypothesis))}</strong>. ${esc(i.observation_assessment.reason||'Conditional forecast available; no hidden fault label used.')}</p>`:''}${i.alerts.map(a=>notice(a.severity+' · '+a.detail)).join('')}<details><summary>Competing explanations and provenance</summary><ul>${i.alternatives.map(x=>`<li>${esc(x)}</li>`).join('')}</ul><p class="case-muted">${esc(i.provenance)}</p></details></section>`;}
function actions(){
 const p=data.plans[0],r=p?.recommendation;
 return heading('Choose an action with evidence.','Compare demand reductions from the selected run’s current state. Studies are advisory; applying a plan changes this simulation only.')+
 `<div class="case-grid">${investigation()}<section class="case-panel"><h2>Compare interventions</h2><form id="case-plan-form" class="case-form"><div class="case-columns">${field('Horizon · minutes','horizon',p?.horizon_min||60,'number','min="5" max="120" required')}${field('Maximum delay · minutes','delay',p?.max_delay_min||0,'number','min="0" max="20" required')}</div><button>Compare demand reductions</button></form><p class="case-muted">Pause the simulation before comparing and applying an intervention. Delayed candidates remain advisory; zero-delay recommendations can be applied explicitly.</p></section></div>`+
 (p?`<section class="case-panel"><span class="case-state">Origin: ${num(p.origin_elapsed_s/60)} simulated min · revision ${p.origin_revision} · ${p.horizon_min} min horizon</span><h2>${r?(r.reduction_pct?'A conditional intervention is available':'No reduction required within these study constraints'):'No candidate meets the declared constraints'}</h2>${r?kpis([['Demand reduction',r.reduction_pct+'%',r.delay_min+' min delay · '+num(r.post_load_percent)+'% resulting load'],['Peak sensitivity result',num(r.sensitivity_peak_c)+' °C',p.version==='halo-study-2'?'16 independent corners · 240 min':'Historical model · recalculate'],['Energy curtailed',num(r.curtailed_kwh)+' kWh','Synthetic · unity power factor']])+chart([{label:'Continue unchanged',color:'#a35539',points:p.baseline.points.map(v=>[v.minute,v.temperature_c])},{label:'Proposed intervention',color:'#317966',points:r.points.map(v=>[v.minute,v.temperature_c])}],p.horizon_min)+`<div class="case-actions"><button data-case="apply-plan" ${p.version!=='halo-study-2'||p.applied||!r.reduction_pct||p.origin_revision!==data.run.revision||r.delay_min!==0?'disabled':''}>${p.applied?'Applied to simulation':!r.reduction_pct?'No reduction to apply':'Apply reduction to this simulation'}</button><button data-open="maintenance">Record maintenance follow-up →</button></div>`:''}<p class="case-muted">${esc(p.note)}</p>${p.version!=='halo-study-2'?notice('Historical plan: recalculate with the current decision model.'):''}<details><summary>Review all ${p.candidates.length} candidates and rejected constraints</summary>${table(['Reduction','Delay','Peak upper','Curtailed','Result'],p.candidates.map(c=>[c.reduction_pct+'%',c.delay_min+' min',num(c.sensitivity_peak_c)+' °C',num(c.curtailed_kwh)+' kWh',c.passes?'Meets stated constraints':esc(c.reasons.join(' '))]))}</details></section>`:'');
}
function referenceBenchmark(){if(!validation)return '<p class="case-muted">Loading recorded evaluation…</p>';if(!validation.available)return notice(validation.note);
 const d=validation.detection;
 return `<section class="case-panel case-benchmark"><p class="eyebrow">REPRODUCIBLE EVALUATION · SEPARATE SYNTHETIC PLANT</p><h2>How well does the reference generalise?</h2><p>${esc(validation.scope)}</p>${table(['Forecast horizon','Model MAE','Persistence MAE','Scored / possible'],validation.forecasts.map(f=>[f.horizon_min+' min',num(f.model_mae_c,3)+' °C',num(f.persistence_mae_c,3)+' °C',f.scored+' / '+f.possible]))}${kpis([['Fault episodes detected',d.events_detected+' / '+d.events_total,'Includes mild faults and slow drift'],['Correct alert precision',num(d.correct_alert_precision*100)+'%','Label agreement among alert minutes'],['False-alarm time',num(d.false_alarm_rate_per_normal_minute*100)+'%',d.false_alarm_minutes+' / '+d.normal_minutes+' normal minutes']])}<details><summary>Protocol, failures and individual cases</summary><p>${esc(validation.protocol.training)}</p><p>${esc(validation.protocol.forecast)}</p><p>${esc(validation.protocol.difficulty)}</p>${table(['Case / seed','Detection delay','False-alarm minutes','Lead to thermal critical'],validation.cases.map(c=>[esc(words(c.scenario))+' / '+c.seed,c.scenario==='healthy'?'Healthy control':c.detection_delay_min==null?'Missed':c.detection_delay_min+' min',String(c.false_alarm_minutes),c.lead_to_thermal_critical_min==null?'Not established':c.lead_to_thermal_critical_min+' min']))}</details><p class="case-muted">${esc(validation.protocol.limits)} These are results for the identified oil-reference and residual-screening methods, not field validation of every feature.</p><p class="case-muted">${esc(validation.laya.recorded_evaluation)}</p><button data-case="download-validation">Download complete benchmark JSON</button></section>`;
}
function warningValue(p){
 const paired=p.paired_lead_time?.threshold_only?.overall,burden=p.alarm_burden?.full_pipeline;
 if(!paired)return '';
 const lead=paired.earlier_subgroup_additional_lead_min,hot=p.forecasts?.find(f=>f.horizon_min===30);
 return `<h3>Additional warning value</h3>${kpis([
  ['Earlier than thresholds',`${paired.full_earlier} / ${paired.critical_cases}`,'Critical synthetic cases'],
  ['Same warning time',String(paired.same_time),`${paired.full_later} later; ${paired.paired_warning_times} paired timestamps`],
  ['Median additional lead',num(paired.additional_lead_min.median)+' min','All paired critical cases, including ties'],
  ['Nuisance episodes',String(burden?.false_alarm_episodes??'—'),`${num(burden?.false_alarm_episodes_per_100_inactive_case_hours,2)} per 100 inactive synthetic case-hours`]
 ])}<p>${lead?.count?`Earlier subgroup: ${num(lead.min)}–${num(lead.max)} minutes, median ${num(lead.median)} minutes. First signals: ${Object.entries(paired.earlier_subgroup_first_warning_kinds||{}).map(([k,v])=>esc(words(k))+': '+v).join(', ')}.`:'No earlier-warning subgroup established.'} A discrepancy warning is not necessarily a forecast benefit.</p>${hot?notice(`30-minute reported hot-spot: ${num(hot.p95_error_c,2)} °C P95 absolute error; ${hot.scored}/${hot.possible} windows scored. Point trajectories are not calibrated safety bounds.`):''}`;
}
function freshEvaluation(){
 const p=validation?.fresh_evaluation;if(!p)return notice('Fresh frozen evaluation has not completed. No unseen-performance claim is available.');
 return `<section class="case-panel"><p class="eyebrow">FROZEN SYNTHETIC EVALUATION · ${esc(p.proof.run_id)}</p><h2>A separate evaluation, frozen before generation.</h2><p>${esc(p.proof.note)}</p>${p.source_matches&&p.artifact_integrity?'<p class="case-muted">Source hashes and the retained protocol/report binding match.</p>':notice('Evaluation binding or current source does not match. Treat these results as historical until reviewed.')}<p>${esc(p.scope)}</p>${warningValue(p)}${table(['Target · 30 min','Model MAE','Persistence MAE','P95 absolute error','Scored / possible'],[['Oil',p.oil_only_forecasts],['Reported hot-spot',p.forecasts]].map(([name,rows])=>{const f=rows.find(x=>x.horizon_min===30);return [name,num(f.model_mae_c,2)+' °C',num(f.persistence_mae_c,2)+' °C',num(f.p95_error_c,2)+' °C',f.scored+' / '+f.possible];}))}<details><summary>Frozen protocol identity</summary><p>Started: ${esc(p.proof.started_at)}. Completed: ${esc(p.proof.completed_at)}.</p><code>${esc(p.proof.protocol_sha256)}</code><p>Internally generated synthetic cases. Not third-party registration, external recordings, independent physical assets or field validation. Hashes detect changes against retained copies, not authorship.</p></details><button data-case="download-validation">Download both evaluations and provenance</button></section>`;
}
function benchmark(){
 const p=validation?.pipeline;if(!p)return notice('Current pipeline evaluation is unavailable. Generate it before presenting performance claims.');
 const rows=values=>values.map(f=>[f.horizon_min+' min',num(f.model_mae_c,2)+' °C',num(f.persistence_mae_c,2)+' °C',num(f.p95_error_c,2)+' °C',f.scored+' / '+f.possible]);
 const heads=['Horizon','Model MAE','Persistence MAE','95th-percentile error','Scored / possible'];
 const passed=p.interventions.filter(x=>x.passed).length,feasible=p.interventions.filter(x=>x.feasible).length;
 return `<section class="case-panel case-benchmark"><p class="eyebrow">RECORDED VALIDATION · ${esc(p.version)}</p><h2>Errors, coverage and useful warning time.</h2><p>${esc(p.scope)}</p>${!p.source_matches?notice('Numerical source changed since this benchmark. Regenerate before presenting these results.'):'<p class="case-muted">Evaluation matches the current numerical source files.</p>'}<h3>Oil-only mode · measured oil target</h3>${p.oil_only_forecasts?table(heads,rows(p.oil_only_forecasts)):notice('Oil-only evaluation unavailable in this historical report.')}<p>Withheld forecasts stay in the denominator. The conditional model is not allowed to continue offering a countdown after detected thermal-model disagreement.</p><details><summary>Reported hot-spot performance and withheld cases</summary>${table(heads,rows(p.forecasts))}${table(['Horizon','Why unscored'],p.forecasts.map(f=>[f.horizon_min+' min',Object.entries(f.withheld_reasons||{}).map(([k,v])=>esc(words(k))+': '+v).join('<br>')]))}</details><details><summary>Disturbance timing and independent plant families</summary><p>The following timing groups are disjoint. Future disturbances were unknown when a forecast was issued; post-disturbance results test the model after observations change. All groups remain included in the headline results.</p>${Object.entries(p.partitions||{}).map(([target,groups])=>`<h3>${esc(words(target))} · 30-minute horizon</h3>${table(['Window','Model MAE','Persistence MAE','P95 error','Coverage'],Object.entries(groups).map(([name,values])=>[esc(words(name)),...rows(values).at(-1).slice(1)]))}`).join('')}${table(['Plant family','Hot-spot MAE · 30 min','Coverage'],Object.entries(p.families||{}).map(([name,values])=>[esc(words(name)),num(values.at(-1).model_mae_c,2)+' °C',values.at(-1).scored+' / '+values.at(-1).possible]))}</details>${warningValue(p)}${comparatorTables(p)}<details><summary>Protocol and individual failures</summary><p>${esc(p.protocol.training)}</p><p>${esc(p.protocol.inputs)}</p><p>${esc(p.protocol.limits)}</p>${table(['Family / case / seed','Detection delay','False alarms','Lead to critical'],p.cases.map(c=>[esc(c.family+' / '+c.scenario)+' / '+c.seed,c.scenario==='healthy'?'Control':c.delay_min==null?'Missed':c.delay_min+' min',c.false_alarm_episodes+' episodes',c.lead_to_critical_min==null?'Not established':c.lead_to_critical_min+' min']))}</details><p><strong>${passed} / ${feasible} feasible interventions</strong> matched simulated action execution. This is a consistency check; it is separate from independent forecast accuracy.</p><button data-case="download-validation">Download evaluation and provenance</button></section><details class="case-panel"><summary>Earlier oil-reference experiment</summary>${referenceBenchmark()}</details>`;
}
function comparatorTables(p){
 const policies=[['full_pipeline','Full observation pipeline'],['without_cusum','Without CUSUM'],['threshold_only','Threshold-only policy']];
 const count=(n,d)=>d?`${n??0} / ${d}`:'No critical crossing';
 const disturbed=p.classes.filter(c=>c.scenario!=='healthy').reduce((n,c)=>n+c.total,0);
 const summary=p.comparators?table(['Policy','Complete expected signals · disturbed cases','Any warning before critical','Expected signals before critical','Healthy-period alarm episodes'],policies.map(([key,name])=>{const c=p.comparators[key];return c?[name,c.expected_signal_set_complete+' / '+disturbed,count(c.any_warning_before_critical,c.critical_events),count(c.complete_before_critical,c.critical_events),String(c.false_alarm_episodes)]:[name,'Unavailable','Unavailable','Unavailable','Unavailable'];})):notice('Policy-level comparison is unavailable in this historical report.');
 const byClass=table(['Condition','Full pipeline: complete signals','Without CUSUM: complete signals','Threshold-only: any early warning','Critical cases'],p.classes.map(c=>{const t=c.comparators?.threshold_only;return [esc(words(c.scenario)),c.detected+' / '+c.total,(c.without_cusum_detected??c.baseline_detected??'—')+' / '+c.total,t?count(t.any_warning_before_critical,t.critical_events):'Not recorded',String(c.critical_events??'—')];}));
 return '<h3>What does the model add over thresholds?</h3><p>The threshold-only policy uses valid observed limits and acquisition holds. It does not run residual analysis, CUSUM or forecasting. The separate without-CUSUM policy retains the other model checks.</p>'+summary+'<details><summary>Compare the same cases by condition</summary>'+byClass+'</details><p class="case-muted">An early electrical warning is useful even if the complete expected diagnostic signal set arrives later. These are separate outcomes; threshold-only alarms do not establish a cooling or sensor root cause. All policies use the same observation prefixes.</p>';
}
function electricalBlind(){
 const b=blindCase,r=b.assessment?.result,first=b.waveforms[0].time_s,last=b.waveforms.at(-1).time_s;
 return `<section class="case-panel case-blind"><h2>Identify the electrical event</h2><p class="case-muted">Sampled synthetic waveforms. The event label stays hidden until assessment is frozen.</p><div class="case-actions"><label>Challenge inputs<select id="blind-mode"><option value="electrical">Electrical waveforms</option><option value="oil_only">Oil temperature</option><option value="oil_and_hotspot">Oil + hot-spot</option></select></label><button data-case="blind-new">New blind event</button><button data-case="blind-assess" ${r?'disabled':''}>Freeze diagnosis</button><button data-case="blind-reveal" ${r?'':'disabled'}>Reveal event</button><button data-case="blind-export">Download evidence</button></div>
 ${chart([{label:'Primary current',color:'#c88936',points:b.waveforms.map(x=>[(x.time_s-first)*1000,x.primary_pu])},{label:'Compensated secondary',color:'#28795e',points:b.waveforms.map(x=>[(x.time_s-first)*1000,x.secondary_compensated_pu])}],(last-first)*1000,num(first*1000)+' ms',num(last*1000)+' ms','Sampled primary and compensated secondary currents in per unit')}
 ${r?`<h3>${esc(words(r.classification))}</h3><p>${esc(r.action)}</p><ul>${[...r.evidence,...r.missing].map(x=>`<li>${esc(x)}</li>`).join('')}</ul>${r.alternatives.length?`<p>Alternatives: ${esc(r.alternatives.map(words).join(', '))}</p>`:''}`:'<p>Freeze the observation-only result to inspect the diagnosis.</p>'}
 ${b.reveal?`<p><strong>Actual event: ${esc(words(b.reveal.label))}</strong> &middot; ${b.correct?'Matched':'Did not match'} &middot; commitment ${b.commitment_verified?'verified':'failed'}</p>`:''}</section>`;
}
function blind(){
 if(blindCase?.domain==='electrical')return electricalBlind();
 const b=blindCase,r=b?.assessment?.result,oil=b?.temperature_mode==='oil_only',target=oil?'oil_c':'hotspot_c',origin=b?.origin_min||120;
 const future=b?.reveal?.rows.filter(x=>x.elapsed_s>origin*60&&x.elapsed_s<=(origin+30)*60)||[];
 const stages=[['01','Observe',!!b],['02','Freeze',!!b?.assessment],['03','Reveal & score',!!b?.reveal]];
 return `<section class="case-panel case-blind"><p class="eyebrow">OBSERVATIONS → FROZEN DECISION → LATER EVIDENCE</p><h2>Can the model defend its decision?</h2><p>Start with a concealed synthetic case or import an oil-temperature recording. The assessor receives electrical and thermal observations; fault labels stay hidden.</p><ol class="case-proof-steps">${stages.map(([n,label,done])=>`<li data-done="${done}"><b>${n}</b><span>${label}</span>${done?'<span aria-label="Complete">✓</span>':''}</li>`).join('')}</ol><div class="case-actions"><label>Challenge inputs<select id="blind-mode"><option value="electrical">Electrical waveforms</option><option value="oil_only" ${b&&oil?'selected':''}>Oil only · infer hot-spot</option><option value="oil_and_hotspot" ${b&&!oil?'selected':''}>Oil + reported hot-spot</option></select></label><button data-case="blind-new">Prepare an unseen case</button>${b?`<button data-case="blind-assess" ${b.assessment?'disabled':''}>Freeze observation assessment</button><button data-case="blind-reveal" ${b.assessment?'':'disabled'}>Reveal later readings</button><button data-case="blind-export">Download experiment</button>`:''}</div>
 <details class="case-import"><summary>Use your own oil-temperature CSV</summary><p>Required: elapsed_s, oil_c, ambient_c, load_percent, voltage_pu. Add hotspot_c for the two-temperature mode. Review the first 70 rows as healthy; use a zero-based forecast origin after that reference. A retrospective recording is known to its uploader. <a href="/static/synthetic-observation-recording.csv" download>Download a labelled synthetic CSV example</a>.</p><form id="case-observation-import" class="case-form"><label>Recording<input name="recording" type="file" accept=".csv,text/csv" required></label>${field('Reference name','name','Reviewed oil recording','text','required minlength="3" maxlength="120"')}${field('Forecast origin · row index','origin',90,'number','required min="70" max="4998"')}<label><input name="reviewed" type="checkbox" required> I reviewed the first 70 rows as healthy oil measurements. This is not a surface-probe recording.</label><label><input name="winding_reviewed" type="checkbox"> I also reviewed the reported hot-spot reference as valid in these 70 healthy rows. Fit winding parameters only if held-out checks pass; unavailable in oil-only mode.</label><button>Import observation case</button></form></details>
 ${b?`<p class="case-muted">${esc(b.name)} · ${esc(b.source)} · origin ${num(origin)} min</p>${chart([{label:oil?'Observed top oil':'Reported hot-spot',color:'#245daf',points:b.observations.map(x=>[x.elapsed_s/60-origin+30,x[target]])}],30,'30 min earlier','Assess now')}<details><summary>Source and commitment</summary><p>${esc(b.note)}</p><p>${esc(b.qualification?.reference_basis)} · Oil fit ${b.qualification?.oil_fit_used?'qualified':'not qualified; illustrative defaults retained'}.</p><p>Winding forecast reference: ${b.qualification?.winding_fit_used?'qualified · fitted projection only; diagnostic screening unchanged':b.qualification?.winding_reference?'qualification not passed; configured parameters retained':'not fitted; configured parameters retained'}. ${esc((b.qualification?.winding_reference?.holds||[]).join(' · '))}</p><code>${esc(b.commitment)}</code></details>`:''}
 ${r?`<div class="case-verdict" data-held="${!r.available}"><p class="eyebrow">${r.available?'CONDITIONAL FORECAST AVAILABLE':'FORECAST WITHHELD'}</p><h3>${esc(r.presentation_headline||((r.analysis?.status&&r.analysis.status!=='NORMAL')?r.analysis.status+' observed condition':words(r.hypotheses?.length?r.hypotheses.join(' + '):r.hypothesis)))}</h3><p><strong>${esc(r.next_action||r.reason)}</strong></p>${(r.observed_alerts||r.analysis?.alerts||[]).map(alert=>`<p class="case-alert ${['CRITICAL','TRIP'].includes(alert.severity)?'critical':''}">${esc(alert.severity)} · ${esc(alert.detail)} · ${esc(alert.value)} (threshold ${esc(alert.threshold)})</p>`).join('')}<p>Diagnostic hypothesis: ${esc(words(r.hypotheses?.length?r.hypotheses.join(' + '):r.hypothesis))}. Diagnosis and forecast availability do not override observed severity.</p><p>${esc(r.capability?.note)}</p><details><summary>What the model assumes</summary><p>${esc(r.assumptions||r.next_action)}</p><p>Pipeline: ${esc(r.version)} · frozen SHA-256 <code>${esc(b.assessment.sha256)}</code></p></details></div>`:''}
 ${b?.reveal?`<h3>Revealed: ${esc(words(b.reveal.meta.scenario))}</h3><p>Commitment ${b.commitment_verified?'verified':'FAILED'} · assessment retained unchanged.</p>${kpis([[oil?'Oil forecast MAE':'Reported hot-spot MAE',r.available?num(b.scores.model_mae_c,2)+' °C':'Withheld','Frozen before later readings were revealed'],['Persistence MAE',r.available?num(b.scores.persistence_mae_c,2)+' °C':'Not scored','Same future observations'],['Forecast coverage',b.scores.count+' / '+b.scores.possible,'No withheld result is counted as an accurate forecast']])}${chart([{label:oil?'Later observed oil':'Later reported hot-spot',color:'#b45d3e',points:future.map(x=>[x.elapsed_s/60-origin,x[target]])},...(r.available?[{label:'Frozen prediction',color:'#245daf',points:r.forecast.points.map(x=>[x.minute,oil?x.oil_c:x.temperature_c])}]:[])],30)}<p class="case-muted">${esc(b.scores.note)}</p>`:''}</section>`;
}
function evidence(){
 return heading('Decisions that survive the reveal.','Observation-only evidence comes first. Inspect model assumptions and simulation consistency separately below.')+`<section class="case-panel external-evidence" id="external-forecast-panel"></section>`+blind()+HaloEvidenceWorkflow.panel()+freshEvaluation()+benchmark()+`<details class="case-panel case-advanced"><summary>Scenario model · selected-run studies and internal consistency</summary><p>This section knows the declared cooling and fault settings. It tests the simulator and action execution; it does not establish blind diagnostic accuracy.</p>`+
 `<div class="case-grid">${investigation()}<section class="case-panel"><h2>Freeze a scenario-model forecast</h2><form id="case-proof-form" class="case-form">${field('Forecast horizon · minutes','horizon',15,'number','min="5" max="120" required')}<button ${data.investigation.forecast_holds.length?'disabled':''}>Freeze this run’s forecast</button></form>${data.investigation.forecast_holds.map(notice).join('')}<div class="case-actions"><button data-case="advance-five">Advance simulation 5 min</button></div><p class="case-muted">Advancing starts the simulation if paused, records five simulated minutes, then pauses it. No hardware command.</p></section></div>`+
 `<section class="case-panel"><h2>Frozen predictions & later observations</h2>${data.proofs.length?data.proofs.map(({proof:p,score:s})=>`<article class="case-record"><span class="case-state">${p.horizon_min} min · origin ${num(p.origin_elapsed_s/60)} min</span><p class="case-alert">Internal consistency check · this forecast and these observations use the same simulated plant. Independent performance appears below.</p><h3>${esc(s.verdict)}</h3>${kpis([['Comparable model MAE',num(s.unchanged_inputs.mae_c,3)+' °C',s.unchanged_inputs.count+' samples'],['Persistence MAE',num(s.unchanged_inputs.persistence_mae_c,3)+' °C','Same observations'],['Changed inputs',String(s.changed_input_samples),s.unqualified_samples+' unqualified samples withheld']])}${chart([{label:'Frozen prediction',color:'#3d648e',points:p.points.map(x=>[x.minute,x.temperature_c])},{label:'Later observations',color:'#b45d3e',points:s.observations.map(x=>[x.minute,x.actual_c])},{label:'Sensitivity upper',color:'#909c91',dash:true,points:p.points.map(x=>[x.minute,x.upper_c])}],p.horizon_min)}<p class="case-muted">${esc(s.note)} ${esc(p.assumptions[1])}</p><details><summary>Frozen provenance</summary><p>${esc(p.assumptions[2])}</p><code>SHA-256 ${esc(p.sha256)}</code><p>${esc(p.profile.reference)}</p></details></article>`).join(''):'<p>No forecast has been frozen for this run. A forecast in another asset’s history is never substituted.</p>'}</section></details>`;
}
function maintenance(){const scope='<div class="case-actions maintenance-scope"><button data-maintenance-scope="simulation" aria-pressed="'+(maintenanceScope==='simulation')+'">Selected simulation run</button><button data-maintenance-scope="reference" aria-pressed="'+(maintenanceScope==='reference')+'">Imported recordings</button></div>';if(maintenanceScope==='reference')return heading('Maintenance linked to its recording.','Imported reference reviews preserve their own asset, source and frozen assessment.')+scope+HaloEvidenceWorkflow.panel();return scope+heading('Close the loop with later evidence.','Each work order belongs to this run. Closure requires recorded investigation, an action, subsequent qualified observations and recovered operation.')+
 `<div class="case-grid">${investigation()}<section class="case-panel"><h2>Create a work order</h2><form id="case-work-form" class="case-form">${field('Action','title',data.investigation.next_check,'text','minlength="5" maxlength="180" required')}${field('Owner / reviewer','owner','','text','minlength="2" required')}<div class="case-columns"><label>Priority<select name="priority"><option value="soon">Soon</option><option value="urgent">Urgent</option><option value="routine">Routine</option></select></label>${field('Due in simulated minutes','due',30,'number','min="0" max="10080" required')}</div><div class="case-columns">${field('Stable recovery · minutes','stable_minutes',10,'number','min="5" max="60" required')}${field('Maximum load · %','max_load_percent',99,'number','min="0" max="99" required')}${field('Maximum hot-spot · °C','max_temperature_c',110,'number','min="20" max="125" required')}</div><p class="case-muted">Closure also requires restored cooling, no active disturbance and a 240-minute thermal corner check below the critical limit.</p><label>Additional acceptance notes<textarea name="acceptance" required minlength="15">Later qualified readings, recovered operating status and a documented independent check.</textarea></label><button>Create run-linked work order</button></form></section></div>`+
 `<section class="case-panel"><h2>Investigation and follow-up</h2>${data.work_orders.length?data.work_orders.map(w=>`<article class="case-record"><span class="case-state">${esc(words(w.status))} · ${esc(w.priority)}</span><h3>${esc(w.title)}</h3><p>${esc(w.owner)} · due at ${num(w.due_elapsed_s/60)} simulated min</p><p>Accept when: ${esc(w.acceptance)}</p>${w.acceptance_rules?`<p class="case-muted">Recorded rules: ${w.acceptance_rules.stable_minutes} stable min · load ≤ ${num(w.acceptance_rules.max_load_percent)}% · hot-spot ≤ ${num(w.acceptance_rules.max_temperature_c)} °C · ${w.acceptance_rules.forecast_horizon_min}-minute forward check${w.acceptance_rules.require_cooling_restored?' · cooling restored':''}.</p>`:''}${w.verification?.eligible?'<p class="case-state">Current evidence meets the recorded numerical rules.</p>':''}${w.trail.map(t=>`<p><strong>${esc(words(t.status))}</strong> · ${num(t.elapsed_s/60)} min — ${esc(t.note)}</p>`).join('')}${w.verification?.holds?.length?notice(w.verification.holds.join(' ')):''}${w.status==='closed'?'<p>Historical closure record retained. Check the current acceptance assessment above; this is not proof of a physical repair.</p>':`<form class="case-form" data-work="${esc(w.id)}"><label>Investigation / action / follow-up evidence<textarea name="note" required minlength="15" placeholder="Describe the check and the evidence supporting this step."></textarea></label>${w.status==='verification_pending'?'<label>Outcome<select name="outcome"><option value="closed">Verify resolution and close</option><option value="stabilized">Temporarily stabilized · issue remains open</option></select></label>':''}<button>${({open:'Record investigation',in_progress:'Record action; await verification',verification_pending:'Record verification outcome',stabilized:'Record further action; await verification'})[w.status]}</button></form>`}</article>`).join(''):'<p>No work orders for this run.</p>'}</section>`;}
function passport(){const p=data.run.profile;return heading('Know what the model is based on.','Record the origin of the parameters. An uploaded surface-temperature trace cannot calibrate an oil-temperature model.')+
 `<div class="case-grid"><section class="case-panel"><h2>Asset and parameter provenance</h2><form id="case-profile-form" class="case-form">${field('Asset name','name',p.name,'text','minlength="3" maxlength="120" required')}<label>Basis<select name="basis">${['illustrative','manufacturer_document','lab_reference','synthetic_reference'].map(x=>`<option value="${x}" ${x===p.basis?'selected':''}>${esc(words(x))}</option>`).join('')}</select></label>${field('Reviewer','reviewer',p.reviewer,'text','minlength="3" required')}<label>Document / measurement reference<textarea name="reference" minlength="5" required>${esc(p.reference)}</textarea></label><label>Impedance basis<select name="impedance_basis">${['illustrative','nameplate','test_report','reviewed_configuration'].map(x=>`<option value="${x}" ${x===(p.impedance_basis||'illustrative')?'selected':''}>${esc(words(x))}</option>`).join('')}</select></label>${field('Impedance reference','impedance_reference',p.impedance_reference||'No impedance reference supplied','text','required minlength="5"')}${field('Impedance reviewer','impedance_reviewer',p.impedance_reviewer||'Unreviewed','text','required minlength="3"')}<button>Save provenance</button></form><p class="case-muted">Recording a reference is an operator assertion, not automatic verification of the source document. Model settings remain editable only before a run starts.</p></section><section class="case-panel"><h2>Identify an oil thermal reference</h2><p>Upload a reviewed healthy period with <code>elapsed_s, oil_c, ambient_c, load_percent</code>. At least 60 readings and 30 minutes with changing load and temperature. Include a complete voltage_pu column when voltage varies; omitted voltage is explicitly assumed nominal.</p><form id="case-reference-form" class="case-form"><label>CSV reference<input type="file" id="case-reference-file" accept=".csv,text/csv"></label><button type="button" data-case="sample-reference">Use labelled synthetic example</button><p id="case-reference-name" class="case-muted">${esc(csvName||'No file selected')}</p>${field('Reference name','name','Oil reference','text','minlength="3" required')}${field('Reviewer','reviewer','','text','minlength="3" required')}<label>Evidence source<select name="source"><option value="synthetic" ${csvSource==='synthetic'?'selected':''}>Synthetic example</option><option value="recorded_oil_reference" ${csvSource==='recorded_oil_reference'?'selected':''}>Recorded oil-temperature reference</option></select></label>${field('Core-loss fraction · assumed unless documented','core_fraction',.133333333333,'number','min="0" max="0.999" step="any" required')}<label><input type="checkbox" name="reviewed" required> I reviewed this period as healthy and confirm this is oil temperature, not a surface probe.</label><button>Fit and validate reference</button></form></section></div><section class="case-panel"><h2>Recorded references</h2>${references.length?references.map(r=>`<article class="case-record"><span class="case-state">${esc(r.source)} · ${r.eligible?'Eligible for a model study':'Qualification not passed'}</span><h3>${esc(r.name)}</h3>${kpis([['Held-out RMSE',num(r.fit.validation_rmse_c,3)+' °C','Recorded-input validation'],['Persistence RMSE',num(r.fit.persistence_rmse_c,3)+' °C','Same held-out period'],['Oil time constant',num(r.fit.oil_tau_min)+' min','Fitted; not winding calibration']])}<p class="case-muted">${esc(r.fit.method)}</p><button data-reference="${esc(r.id)}" ${r.eligible?'':'disabled'}>Create a new run with these oil parameters</button></article>`).join(''):'<p>No oil reference has been fitted. Defaults remain illustrative.</p>'}</section>`;}
function rehearsal(){return heading('A five-minute story with inspectable evidence.','Use one run from first signal to follow-up. Keep prediction error and measurement limits visible when presenting.')+
 `<section class="case-panel"><div class="case-actions"><button data-case="rehearse">Prepare a new rehearsal run</button><a href="/static/submission-guide.html">Open presenter notes ↗</a></div><p class="case-muted">Creates a labelled simulation with 110% demand, degraded cooling and 35 °C ambient. Existing runs are retained.</p>${[
 ['Identify this run','Keep the simulation source and run ID visible. Open Review this run and read the hot-spot, critical reference and operating warning.','operate'],
 ['Inspect the observation','Follow the selected run’s signals and recorded response. Review the observation-only assessment in its maintenance investigation, including any forecast hold.','maintenance'],
 ['Compare a conditional action','Inspect the scenario study using declared cooling. Apply an explicit nonzero reduction if available, then advance this simulation five minutes. The 240-minute sensitivity check is not validated four-hour prediction.','operate'],
 ['Record the follow-up','Keep this run selected. Record owner, inspection, action and numerical acceptance rules. Demonstrate a hold or temporary stabilization while cooling remains impaired.','maintenance'],
 ['Export and defend the method','Export this run. Introduce dataset-level evaluation separately: paired warning time, false alarms, forecast error tails and coverage. Imported recordings and physical acquisition are optional separately identified follow-ups.','evidence']
 ].map(([title,note,dest],i)=>`<div class="case-step"><b>0${i+1}</b><div><h3>${title}</h3><p>${note}</p><button data-open="${dest}">Open ${dest==='operate'?'Control centre':dest==='actions'?'Action Lab':words(dest)} →</button></div></div>`).join('')}</section>`;}
function inspector(){const t=data.run.telemetry;return heading('Every channel keeps its meaning.','This view follows the same industrial run as the rest of the workspace.')+`<section class="case-panel">${table(['Channel','Value','Meaning'],[['Primary voltage',num(t.primary_voltage)+' V','Modelled line-to-line RMS'],['Primary current',num(t.primary_current,3)+' A','Modelled line RMS'],['Secondary voltage',num(t.secondary_voltage)+' V','Modelled line-to-line RMS'],['Secondary current',num(t.secondary_current,3)+' A','Modelled line RMS'],['Top oil',num(t.oil_temperature)+' °C','Simulated oil temperature'],['Hot-spot',num(t.hotspot_temperature)+' °C','Simulated thermal state'],['Reported temperature',num(t.transformer_temperature)+' °C','Can include an injected sensor discrepancy']])}</section>`+investigation();}
function assistant(){return heading('A decision you can inspect.','The selected run’s numerical evidence is authoritative. Optional language-model interpretation does not control protection.')+investigation()+`<section class="case-panel"><h2>AI evaluation status</h2><p>${esc(data.investigation.ai_status)}</p><p>Review model benchmarks and imported observations in Evidence.</p><button data-open="evidence">Review prediction evidence →</button></section>`;}
function arena(){return heading('An independent blind challenge.','The challenge uses its own synthetic case, separate from your selected industrial asset.')+`<section class="case-panel"><h2>Let a judge choose the disturbance.</h2><p>The existing challenge hides its case, records the assessment and reveals the evidence afterwards. Its results do not replace the selected run’s measurements.</p><a href="/judge" target="_blank" rel="noopener">Open the independent judge console ↗</a><button data-open="evidence">Review model evaluation →</button></section>`;}
function render(){
 if(!S.industrial()||!panel()||!data||data.run.id!==S.run()?.id)return;
 const functions={actions,evidence,maintenance,passport,demo:rehearsal,twin:inspector,integrations:assistant,arena};
 const container=panel();container.innerHTML=functions[view()]();
 if(view()==='evidence')window.HaloExternal?.mount();
 container.querySelectorAll('[data-maintenance-scope]').forEach(b=>b.onclick=()=>{maintenanceScope=b.dataset.maintenanceScope;render();});
 if(container.querySelector('#case-reference-workflow'))HaloEvidenceWorkflow.mount({record:blindCase,onCase:b=>{blindCase=b;localStorage.setItem('halo-blind-case',b.id);render();}});
 container.querySelectorAll('[data-open]').forEach(b=>b.onclick=()=>b.dataset.open==='maintenance'?window.HaloCase.openRunMaintenance(S.run()?.id).catch(e=>error(e.message)):H.view(b.dataset.open));
 container.querySelectorAll('[data-case]').forEach(b=>b.onclick=()=>task(()=>action(b.dataset.case)));
 const form=(id,fn)=>{const f=$(id);if(f)f.onsubmit=e=>{e.preventDefault();task(()=>fn(new FormData(f)));};};
 form('case-observation-import',async f=>{const file=f.get('recording');if(!file?.size||file.size>1000000)throw Error('Choose a CSV up to 1 MB.');blindCase=await api('/twin/challenges/import',{request_id:crypto.randomUUID(),temperature_mode:$('blind-mode').value,csv_text:await file.text(),name:f.get('name'),origin_index:Number(f.get('origin')),healthy_reference_reviewed:f.has('reviewed'),winding_reference_reviewed:$('blind-mode').value==='oil_and_hotspot'&&f.has('winding_reviewed')});localStorage.setItem('halo-blind-case',blindCase.id);});
 form('case-plan-form',async f=>{await api(endpoint('/plans'),study(Number(f.get('horizon')),Number(f.get('delay'))));await load();});
 form('case-proof-form',async f=>{await api(endpoint('/proofs'),study(Number(f.get('horizon'))));await load();});
 form('case-work-form',async f=>{await api(endpoint('/work'),{request_id:crypto.randomUUID(),revision:data.run.revision,title:f.get('title'),owner:f.get('owner'),priority:f.get('priority'),due_sim_min:Number(f.get('due')),acceptance:f.get('acceptance'),acceptance_rules:{stable_minutes:Number(f.get('stable_minutes')),max_load_percent:Number(f.get('max_load_percent')),max_temperature_c:Number(f.get('max_temperature_c')),forecast_horizon_min:240,require_cooling_restored:true}});await load();});
 form('case-profile-form',async f=>{await window.HaloOperations.act('profile',{profile:Object.fromEntries(f)});await load();});
 form('case-reference-form',async f=>{if(!csvText)throw Error('Choose a CSV or load the labelled example first.');await api('/twin/references',{request_id:crypto.randomUUID(),name:f.get('name'),reviewer:f.get('reviewer'),source:csvName.startsWith('SYNTHETIC')?'synthetic':f.get('source'),temperature_kind:'oil',healthy_reviewed:f.has('reviewed'),csv_text:csvText,core_fraction:Number(f.get('core_fraction'))});references=await api('/twin/references');});
 const input=$('case-reference-file');if(input)input.onchange=async()=>{const f=input.files[0];if(!f)return;if(f.size>1000000){error('CSV limit is 1 MB.');return;}csvText=await f.text();csvName=f.name;csvSource='recorded_oil_reference';input.form.elements.source.value=csvSource;$('case-reference-name').textContent=csvName;};
 container.querySelectorAll('[data-reference]').forEach(b=>b.onclick=()=>task(async()=>{const s=await api('/twin/references/'+encodeURIComponent(b.dataset.reference)+'/run',{request_id:crypto.randomUUID()});await window.HaloOperations.adopt(s);await load();H.view('operate');}));
 container.querySelectorAll('[data-work]').forEach(f=>f.onsubmit=e=>{e.preventDefault();task(async()=>{const w=data.work_orders.find(w=>w.id===f.dataset.work);await api(endpoint('/work/'+encodeURIComponent(w.id)),{status:w.status==='verification_pending'?new FormData(f).get('outcome'):({open:'in_progress',in_progress:'verification_pending',stabilized:'verification_pending'})[w.status],note:new FormData(f).get('note'),revision:w.revision});await load();});});
 if(busy)container.querySelectorAll('button').forEach(b=>b.disabled=true);
}
function renderInspections(rows,physical=false){
 const container=physical?$('view-maintenance'):panel('maintenance');if(!container)return;
 const sectionId=physical?'prototype-mobile-inspections':'case-mobile-inspections';
 let section=container.querySelector('#'+sectionId);
 if(!section){section=document.createElement('section');section.id=sectionId;section.className='case-panel';container.append(section);}
 section.hidden=!rows.length;
 section.innerHTML='<h2>Mobile inspections</h2>'+rows.map(r=>`<article class="case-record"><b>${esc(words(r.component))}</b><p>${esc(r.note)}</p><small>${esc(new Date(r.captured_at).toLocaleString())}${r.independent_surface_c==null?'':' &middot; Independent surface: '+esc(r.independent_surface_c)+' &deg;C'}</small>${r.photo?'<p><button data-inspection-photo="'+esc(r.photo.id)+'">View photo</button></p>':''}</article>`).join('');
 section.querySelectorAll('[data-inspection-photo]').forEach(b=>b.onclick=async()=>{try{const response=await HaloAuth.fetch('/api/halo/attachments/'+encodeURIComponent(b.dataset.inspectionPhoto));if(!response.ok)throw Error('Photo could not be loaded.');const url=URL.createObjectURL(await response.blob());const a=document.createElement('a');a.href=url;a.target='_blank';a.rel='noopener';a.click();setTimeout(()=>URL.revokeObjectURL(url),60000);}catch(e){error(e.message);}});
}
let inspecting=false;
setInterval(async()=>{const source=S.source();if(inspecting||document.hidden||view()!=='maintenance'||!['industrial','prototype'].includes(source)||(source==='industrial'&&!S.run()))return;inspecting=true;const id=S.run()?.id;try{const rows=await api('/mobile/inspections?source='+source+(source==='industrial'?'&run_id='+encodeURIComponent(id):''));if(view()==='maintenance'&&S.source()===source&&(source==='prototype'||S.run()?.id===id))renderInspections(rows,source==='prototype');}catch{}finally{inspecting=false;}},3000);
async function action(name){
 if(name==='blind-new'){blindCase=await api('/twin/challenges',{request_id:crypto.randomUUID(),temperature_mode:$('blind-mode').value==='electrical'?'oil_only':$('blind-mode').value,domain:$('blind-mode').value==='electrical'?'electrical':'thermal'});localStorage.setItem('halo-blind-case',blindCase.id);return;}
 if(name==='blind-assess'){blindCase=await api('/twin/challenges/'+encodeURIComponent(blindCase.id)+'/assess',{});return;}
 if(name==='blind-reveal'){blindCase=await api('/twin/challenges/'+encodeURIComponent(blindCase.id)+'/reveal',{});return;}
 if(name==='blind-export'){const id=blindCase.id;await window.HaloEvidenceWorkflow.downloadRaw('/twin/challenges/'+encodeURIComponent(id),id+'.json',()=>blindCase?.id===id);return;}
 if(name==='refresh'){validation=await api('/twin/validation');return load();}if(name==='export')return window.HaloOperations.export();
 if(name==='apply-plan'){const s=await api(endpoint('/apply-plan'),{plan_id:data.plans[0].id,revision:data.run.revision});await window.HaloOperations.adopt(s);return load();}
 if(name==='advance-five'){if(!data.run.running)await window.HaloOperations.act('start');await window.HaloOperations.act('step',{seconds:300});await window.HaloOperations.act('pause');return load();}
 if(name==='sample-reference'){const r=await fetch('/static/synthetic-oil-reference.csv');if(!r.ok)throw Error('Synthetic example unavailable');csvText=await r.text();csvName='SYNTHETIC · seeded reference example';csvSource='synthetic';return;}
 if(name==='download-validation'){await window.HaloEvidenceWorkflow.downloadRaw('/twin/validation','neuratwin-synthetic-benchmark.json');return;}
 if(name==='rehearse'){
   const s=await api('/twin/runs',{request_id:crypto.randomUUID(),profile:{name:'Judge rehearsal · labelled simulation',basis:'illustrative',reference:'Demonstration assumptions; no field accuracy claim',reviewer:'Neura Rangers'}});
   await window.HaloOperations.adopt(s);await window.HaloOperations.act('inputs',{inputs:{...s.inputs,load_percent:110,cooling:'degraded',ambient_c:35}});await load();H.view('operate');
 }
}
for(const name of views){const host=$('view-'+name);if(!host)continue;const p=document.createElement('div');p.id='case-'+name;p.className='industrial-panel';p.innerHTML='<p class="case-muted">Loading the selected industrial run…</p>';host.append(p);}
$('session-source').onchange=()=>window.HaloOperations.selectSource($('session-source').value).then(()=>{if(S.industrial())load();else if(view()==='operate'&&S.source()==='reference')H.view('twin');}).catch(e=>error(e.message));
$('case-more').onclick=()=>{const nav=document.querySelector('.tabs'),expanded=nav.dataset.expanded!=='true';nav.dataset.expanded=String(expanded);$('case-more').querySelector('span').textContent=expanded?'Fewer tools':'More tools';};
window.addEventListener('halo:view',e=>{if(S.industrial()&&views.includes(e.detail)){if(!S.run())panel().innerHTML='<section class="case-panel"><h2>Select an industrial run first.</h2><p>Create or open a run in Control centre. This view will use that same asset.</p><button data-empty-open>Open Control centre →</button></section>';else panel().innerHTML='<p class="case-muted" role="status">Loading the selected case…</p>';panel()?.querySelector('[data-empty-open]')?.addEventListener('click',()=>H.view('operate'));load();}});
window.addEventListener('halo:run',()=>{const key=S.run()?.id;if(key!==lastRun){data=null;lastRun=key;for(const name of views)panel(name).innerHTML='<p class="case-muted">Loading this asset’s records…</p>';}if(!loading&&views.includes(view()))load();});
window.addEventListener('halo:session',()=>{if(S.industrial()&&views.includes(view()))load();});
window.addEventListener('halo:ready',()=>{const saved=localStorage.getItem('halo-blind-case');if(saved)api('/twin/challenges/'+encodeURIComponent(saved)).then(b=>{blindCase=b;if(view()==='evidence')render();}).catch(()=>localStorage.removeItem('halo-blind-case'));api('/twin/validation').then(v=>{validation=v;if(view()==='evidence')render();}).catch(e=>{validation={available:false,note:e.message};});api('/twin/references').then(r=>{references=r;if(view()==='passport')render();}).catch(()=>{});});
window.HaloCase={openRunMaintenance:async runId=>{
 if(!S.industrial()||!S.run()||S.run().id!==runId)throw Error('The selected simulation changed. Return to its Control centre before continuing this investigation.');
 if(busy)throw Error('Wait for the current case operation to finish.');
 maintenanceScope='simulation';H.view('maintenance');await load();
 if(!S.industrial()||S.run()?.id!==runId)throw Error('The selected source changed while loading maintenance. Review the current source before proceeding.');
}};
const quick=document.createElement('div');quick.className='case-actions';quick.innerHTML='<button data-quick="evidence">Investigate & prove →</button><button data-quick="actions">Full intervention study →</button><button data-quick="maintenance">Maintenance follow-up →</button>';document.querySelector('#op-workspace .op-next').append(quick);quick.querySelectorAll('button').forEach(b=>b.onclick=()=>b.dataset.quick==='maintenance'?window.HaloCase.openRunMaintenance(S.run()?.id).catch(e=>error(e.message)):H.view(b.dataset.quick));
})();
